package com.anapocket.auto

import android.content.Context
import android.content.ContextWrapper
import android.content.SharedPreferences
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/** Android JSON/preferences behavior, isolated namespaces and files. Never invokes any official App. */
object CheckinStoreProbe {
    fun run(ctx:Context){
        val id="fixture_"+CheckinReceiptPolicy.id().replace("-","")
        val fixture=object:ContextWrapper(ctx.applicationContext){
            override fun getSharedPreferences(name:String,mode:Int):SharedPreferences=super.getSharedPreferences(id+"_"+name,mode)
            override fun getFilesDir():File=File(super.getFilesDir(),id).apply{mkdirs()}
        }
        val before=Prefs.loadBlocking(ctx).toJson()
        val realDailyBefore=DailyAdStore.counters(ctx,TokyoDate.of()).toString()
        val date="2040-01-01";val tomorrow="2040-01-02" // fixture dates, never changes the device clock
        val a=CheckinStore(fixture,CheckinApp.RAKUTEN);val b=CheckinStore(fixture,CheckinApp.STEAK)
        val cases=JSONArray()
        fun verify(name:String,ok:Boolean){cases.put(JSONObject().put("case",name).put("passed",ok))}
        verify("new_modules_default_off",!a.config().enabled&&!b.config().enabled)
        a.configure(CheckinConfig(true,11,12));verify("config_namespaces_independent",a.config().enabled&&!b.config().enabled&&b.config().hour==9&&b.config().minute==30)
        verify("first_reservation_allowed",a.reserve("points","fixture-r1",date))
        verify("duplicate_reservation_rejected",!CheckinStore(fixture,CheckinApp.RAKUTEN).reserve("points","fixture-r2",date))
        a.recover();verify("crash_is_unconfirmed_preserves_reservation",a.read("points",date)?.optString("state")=="UNCONFIRMED"&&a.read("points",date)?.optBoolean("reserved")==true)
        verify("crash_does_not_replay",!a.reserve("points","fixture-r3",date))
        a.reserve("lottery1","fixture-l1",date)
        verify("submission_reserved_before_tap",a.submitted("lottery1","fixture-l1",date))
        verify("same_start_never_submitted_twice",!CheckinStore(fixture,CheckinApp.RAKUTEN).submitted("lottery1","fixture-l1",date)&&a.read("lottery1",date)?.optString("phase")=="START_SUBMITTED")
        a.reserve("pickup","fixture-p",date)
        verify("pickup_current_progress_reserved_before_choice",a.pickupStep("fixture-p",date,9))
        verify("pickup_uncertain_choice_cannot_repeat",!CheckinStore(fixture,CheckinApp.RAKUTEN).pickupStep("fixture-p",date,9))
        verify("pickup_official_decrement_can_resume",a.pickupStep("fixture-p",date,8))
        verify("pickup_pr_navigation_fenced_separately",a.pickupNext("fixture-p",date,7)&&!a.pickupNext("fixture-p",date,7)&&a.pickupStep("fixture-p",date,7))
        a.noteDispatch(date,1234,"FIXTURE_ALARM");val trigger=a.dispatchInfo(date)!!.getLong("actualTriggerAt");a.waiting(date,"FIXTURE_ANA_WINDOW")
        verify("resume_keeps_original_schedule_and_trigger",CheckinStore(fixture,CheckinApp.RAKUTEN).dispatchInfo(date)?.optLong("scheduledAt")==1234L&&a.dispatchInfo(date)?.optLong("actualTriggerAt")==trigger&&a.dispatchInfo(date)?.optString("waitReason")=="FIXTURE_ANA_WINDOW")
        verify("new_business_date_independent",a.reserve("points","fixture-r4",tomorrow)&&a.read("points",date)?.optString("state")=="UNCONFIRMED")
        a.update("points","fixture-r4",CheckinState.PREEMPTED,"fixture_ANA",date=tomorrow)
        verify("preempt_preserves_reservation",!a.reserve("points","fixture-r5",tomorrow)&&a.read("points",tomorrow)?.optString("state")=="PREEMPTED")
        b.reserve("darts","fixture-s1",date)
        verify("prior_date_navigation_never_erases_or_adopts_today",b.olderTaskExists("darts",tomorrow)&&!b.olderTaskExists("darts",date)&&b.read("darts",tomorrow)==null)
        verify("darts_pull_requires_started_game",!b.submitDartsPull("fixture-s1",date)&&b.submitted("darts","fixture-s1",date))
        verify("darts_pull_single_submission_across_recreation",b.submitDartsPull("fixture-s1",date)&&!CheckinStore(fixture,CheckinApp.STEAK).submitDartsPull("fixture-s2",date))
        b.update("darts","fixture-s1",CheckinState.UNCONFIRMED,"screenshot_3",date=date)
        verify("new_schema_snapshot_error_never_clears_issued_pull",!b.reconcileUnissuedDartsPull("fixture-s1",date,true)&&b.read("darts",date)?.optBoolean("pullSubmitted")==true)
        b.update("darts","fixture-s1",CheckinState.SUCCESS,rewardType="FIXTURE_COUPON_NOT_REAL",amount="17",confirmed=true,evidence="FIXTURE_ONLY",date=date)
        b.update("darts","fixture-s2",CheckinState.FAILED,"late_callback",date=date)
        verify("terminal_reward_immutable",b.read("darts",date)?.optString("state")=="SUCCESS"&&b.read("darts",date)?.optString("rewardAmount")=="17")
        verify("assets_never_combined",a.read("points",date)?.optString("rewardType")=="楽天ポイント"&&b.read("darts",date)?.optString("rewardType")=="FIXTURE_COUPON_NOT_REAL")
        a.hold("fixture_verification");a.recover();verify("human_hold_persisted",CheckinStore(fixture,CheckinApp.RAKUTEN).hold()=="fixture_verification")
        verify("daily_dispatch_dedup_independent",a.markDispatch(date)&&!a.markDispatch(date)&&b.markDispatch(date))
        val today=TokyoDate.of()
        b.configure(CheckinConfig(true,9,30));b.pending(today)
        verify("startup_dispatch_marked_once",b.markDispatch(today))
        b.beginRun("fixture-startup-before-task",today)
        verify("startup_clears_pending_without_inventing_business_record",b.pendingDate()==null&&b.all(today).isEmpty())
        CheckinStore(fixture,CheckinApp.STEAK).recover()
        verify("death_before_first_task_restores_pending_despite_dispatch_dedup",b.pendingDate()==today&&!b.markDispatch(today)&&b.all(today).isEmpty())
        b.beginRun("fixture-old-controller",today);b.beginRun("fixture-new-controller",today)
        verify("old_controller_cannot_clear_new_startup_journal",!b.finishRun("fixture-old-controller"))
        b.recover();verify("new_startup_journal_survives_old_cleanup",b.pendingDate()==today)
        b.beginRun("fixture-normal-end",today)
        verify("normal_or_timeout_finish_clears_own_journal",b.finishRun("fixture-normal-end"))
        b.recover();verify("normal_or_timeout_finish_does_not_create_retry_loop",b.pendingDate()==null)
        b.beginRun("fixture-live-startup",today)
        b.recover{"fixture-live-startup"}
        verify("schedule_restore_does_not_recover_live_startup",b.pendingDate()==null&&b.all(today).isEmpty())
        b.recover();verify("same_startup_recovers_only_after_lease_is_gone",b.pendingDate()==today)
        b.beginRun("fixture-preempted-startup",today)
        verify("preemption_atomically_clears_journal_and_restores_pending",b.finishRun("fixture-preempted-startup","FIXTURE_ANA_PREEMPT")&&b.pendingDate()==today)
        b.beginRun("fixture-service-disconnected",today)
        verify("service_disconnect_restores_pending_for_reconnection",b.finishRun("fixture-service-disconnected","accessibility_disconnected")&&b.pendingDate()==today)
        b.beginRun("fixture-user-stopped",today);b.finishRun("fixture-user-stopped");b.recover()
        verify("user_stop_does_not_resume_after_recovery",b.pendingDate()==null)
        b.beginRun("fixture-old-date-startup","2000-01-01");b.recover()
        verify("expired_startup_does_not_become_today_task",b.pendingDate()==null)
        b.hold("fixture_manual_required");b.beginRun("fixture-held-startup",today);b.recover()
        verify("held_startup_does_not_resume",b.pendingDate()==null&&b.hold()=="fixture_manual_required")
        b.clearHold();b.configure(CheckinConfig(false,9,30));b.beginRun("fixture-disabled-startup",today);b.recover()
        verify("disabled_startup_does_not_resume",b.pendingDate()==null)
        b.configure(CheckinConfig(true,9,30));b.reserve("darts","fixture-reserved-before-death",today)
        b.beginRun("fixture-reserved-before-death",today);b.recover()
        verify("startup_recovery_preserves_unknown_reservation_and_never_resubmits",b.pendingDate()==today&&b.read("darts",today)?.optString("state")=="UNCONFIRMED"&&b.read("darts",today)?.optBoolean("reserved")==true&&!b.reserve("darts","fixture-must-not-replay",today))
        b.update("darts","fixture-live-task",CheckinState.RUNNING,date=today);b.beginRun("fixture-live-task",today)
        b.recover{"fixture-live-task"}
        verify("schedule_restore_does_not_reconcile_live_running_task",b.pendingDate()==null&&b.read("darts",today)?.optString("state")=="RUNNING")
        b.recover();verify("lost_running_lease_reconciles_without_replay",b.pendingDate()==today&&b.read("darts",today)?.optString("state")=="UNCONFIRMED"&&!b.reserve("darts","fixture-forbidden-replay",today))
        val proved=b.read("darts",date).toString();b.beginRun("fixture-proof-preserved",today);b.recover()
        verify("startup_recovery_does_not_change_previous_confirmed_reward",b.read("darts",date).toString()==proved)
        b.beginRun("fixture-current-writer",today)
        val beforeStaleWrite=b.read("darts",today).toString();var staleCallbackRan=false
        val staleWrite=b.withActiveRun("fixture-old-writer"){staleCallbackRan=true;b.update("darts","fixture-old-writer",CheckinState.FAILED,"must_not_write",date=today)}
        verify("old_callback_cannot_write_new_run_ledger",staleWrite==null&&!staleCallbackRan&&b.read("darts",today).toString()==beforeStaleWrite)
        verify("current_run_can_mutate_under_same_store_lock",b.withActiveRun("fixture-current-writer"){"accepted"}=="accepted")
        b.finishRun("fixture-current-writer")
        verify("finished_run_cannot_execute_delayed_business_mutation",b.withActiveRun("fixture-current-writer"){staleCallbackRan=true;true}==null&&!staleCallbackRan)
        OfficialAdStore.observe(fixture,today,23,"fixture-official","ISOLATED_FIXTURE")
        val reservedOfficial=checkNotNull(OfficialAdStore.reserve(fixture,today,"fixture-official",23))
        OfficialAdStore.finish(fixture,today,reservedOfficial.runId,reservedOfficial.index,AdState.UNCONFIRMED,false,false,"ad_timeout_95s",23,-1,"fixture_unknown")
        val unknownOfficial=OfficialAdStore.attempts(fixture,today).single()
        verify("daily_recovery_requires_departure_proof",!OfficialAdStore.beginBoundRecovery(fixture,today,unknownOfficial,false))
        verify("daily_recovery_binds_original_attempt",OfficialAdStore.beginBoundRecovery(fixture,today,unknownOfficial,true))
        verify("daily_recovery_rejects_counter_jump",!OfficialAdStore.finishBoundRecovery(fixture,today,unknownOfficial,AdReceipt(AdState.REWARD_CONFIRMED,true,true,25),"fixture_bad_jump"))
        verify("daily_recovery_requires_official_reward_receipt",!OfficialAdStore.finishBoundRecovery(fixture,today,unknownOfficial,AdReceipt(AdState.UNCONFIRMED,true,false,24),"fixture_counter_only"))
        verify("daily_recovery_confirms_existing_not_new",OfficialAdStore.finishBoundRecovery(fixture,today,unknownOfficial,AdReceipt(AdState.REWARD_CONFIRMED,true,true,24),"fixture_realistic_receipt"))
        val reviewedOfficial=OfficialAdStore.attempts(fixture,today).single()
        verify("daily_recovery_preserves_run_index_start_and_old_failure",reviewedOfficial.runId==unknownOfficial.runId&&reviewedOfficial.index==unknownOfficial.index&&reviewedOfficial.startedAt==unknownOfficial.startedAt&&reviewedOfficial.failureReason.contains("ad_timeout_95s"))
        verify("daily_recovery_cannot_credit_twice",!OfficialAdStore.finishBoundRecovery(fixture,today,unknownOfficial,AdReceipt(AdState.REWARD_CONFIRMED,true,true,24),"fixture_duplicate"))
        OfficialAdStore.observe(fixture,today,24,"fixture-official-2","ISOLATED_FIXTURE")
        val bounded=checkNotNull(OfficialAdStore.reserve(fixture,today,"fixture-official-2",24))
        OfficialAdStore.finish(fixture,today,bounded.runId,bounded.index,AdState.UNCONFIRMED,false,false,"ad_timeout_95s",24,-1,"fixture_unknown_2")
        val unknownBounded=OfficialAdStore.attempts(fixture,today).last()
        verify("daily_recovery_first_bound_request",OfficialAdStore.beginBoundRecovery(fixture,today,unknownBounded,true))
        verify("daily_recovery_second_bound_request",OfficialAdStore.beginBoundRecovery(fixture,today,unknownBounded,true))
        verify("daily_recovery_third_request_rejected",!OfficialAdStore.beginBoundRecovery(fixture,today,unknownBounded,true))
        verify("real_daily_counters_unchanged_by_fixtures",realDailyBefore==DailyAdStore.counters(ctx,TokyoDate.of()).toString())
        val startDate="2040-02-01"
        b.reserve("darts","fixture-unissued-start",startDate);b.submitted("darts","fixture-unissued-start",startDate)
        b.update("darts","fixture-unissued-start",CheckinState.UNCONFIRMED,"darts_start_changed_after_reservation",date=startDate)
        verify("only_known_unissued_start_may_relocate_entry",b.mayLocateUnissuedDartsStart(startDate))
        verify("unissued_start_needs_actual_same_start_page",!b.reconcileUnissuedDartsStart("fixture-review",startDate,false))
        b.update("darts","fixture-readonly",CheckinState.UNCONFIRMED,"readonly_review",date=startDate)
        verify("known_predispatch_start_failure_reconciles_from_original_history",b.reconcileUnissuedDartsStart("fixture-review",startDate,true)&&b.read("darts",startDate)?.optString("phase")=="ENTRY_RESERVED")
        verify("preflight_schema_two_preserved_before_dispatch",b.submitted("darts","fixture-new-start",startDate,preflightVerified=true)&&b.read("darts",startDate)?.optInt("submissionSchemaVersion")==2)
        b.update("darts","fixture-new-start",CheckinState.UNCONFIRMED,"darts_start_changed_after_reservation",date=startDate)
        verify("verified_new_submission_cannot_reopen_entry",!b.mayLocateUnissuedDartsStart(startDate))
        verify("new_verified_submission_is_never_cleared_by_old_failure_reason",!b.reconcileUnissuedDartsStart("fixture-forbidden",startDate,true)&&b.read("darts",startDate)?.optString("phase")=="START_SUBMITTED")
        val bonusDate="2040-03-10"
        a.reserve("bonus","fixture-bonus",bonusDate)
        verify("bonus_stop_requires_submitted_start",!a.submitBonusStop("fixture-bonus",bonusDate))
        a.submitted("bonus","fixture-bonus",bonusDate,preflightVerified=true)
        verify("bonus_stop_same_draw_once",a.submitBonusStop("fixture-bonus",bonusDate))
        verify("bonus_stop_persisted_no_replay",!CheckinStore(fixture,CheckinApp.RAKUTEN).submitBonusStop("fixture-bonus-retry",bonusDate))
        verify("ana_settings_unchanged",before==Prefs.loadBlocking(ctx).toJson())
        val bitmap=android.graphics.Bitmap.createBitmap(720,1650,android.graphics.Bitmap.Config.ARGB_8888)
        val canvas=android.graphics.Canvas(bitmap);canvas.drawColor(android.graphics.Color.WHITE)
        val paint=android.graphics.Paint().apply{color=android.graphics.Color.rgb(201,90,85)}
        canvas.drawRect(100f,250f,600f,750f,paint) // distractor wheel, must never be dragged
        canvas.drawRect(360f,945f,385f,1155f,paint)
        fun png():ByteArray=java.io.ByteArrayOutputStream().also{bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)}.toByteArray()
        val hint=CheckinLine("引ってはなす",464,1034,492,1180)
        val pull=CheckinOcr.dartPull(png(),listOf(hint))
        verify("dart_visual_target_excludes_red_wheel",pull!=null&&pull.arrow.x in 360..385&&pull.arrow.y>900&&pull.endY>1155)
        verify("dart_requires_current_instruction",CheckinOcr.dartPull(png(),emptyList())==null)
        val status=CheckinLine("う達成",100,840,170,865)
        paint.color=android.graphics.Color.rgb(0,140,0);canvas.drawRect(100f,840f,170f,865f,paint)
        verify("green_check_glyph_normalized_with_image_proof",CheckinOcr.normalizeGreenStatus(png(),listOf(status)).single().text=="達成")
        paint.color=android.graphics.Color.GRAY;canvas.drawRect(100f,840f,170f,865f,paint)
        verify("grey_status_not_promoted_by_text",CheckinOcr.normalizeGreenStatus(png(),listOf(status)).single().text=="う達成")
        bitmap.recycle()
        val passed=(0 until cases.length()).all{cases.getJSONObject(it).getBoolean("passed")}
        Evidence.write(ctx,"r46_store_controlled_"+System.currentTimeMillis()+".json",JSONObject().put("source","ISOLATED_ANDROID_PREFERENCES_FIXTURES_NO_OFFICIAL_UI_OR_REWARD").put("phoneTime",TokyoDate.time()).put("fixtureNamespace",id).put("allPassed",passed).put("cases",cases).toString(2))
        check(passed){"isolated_store_test_failed"}
    }
}
